178	 * a non-404 upstream failure going forward.
179	 */
180	async function fetchJsonWithFallback<T>(
181	  url: string,
182	  parse: (json: unknown) => T | null,
183	  fallback: T,
184	  label: string,
185	): Promise<T> {
186	  try {
