191	      console.error(
192	        `${label}: non-404 upstream failure HTTP ${response.status} — body=${sanitizeLoggedBody(body)}`
193	      );
194	      return fallback;
195	    }
196	    return parse(await response.json()) ?? fallback;
197	  } catch (error) {
198	    console.error(`${label}: failed`, error);
199	    return fallback;
200	  }
201	}
